import * as React from "react";
import { graphql, Link } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";

export default function ServicesPage() {
  const { t } = useTranslation();
  const { language } = useI18next();

  const siteUrl = "https://riano.ca";
  const pathname = language === "fr" ? "/fr/services/" : "/en/services/";

  const servicesItems = t("services.items", { returnObjects: true }) as Array<{
    key: string;
    title: string;
    desc: string;
    href: string;
  }>;

  return (
    <Layout data={info}>
      <SEO
        data={info}
        titleKey="servicesHub.meta.title"
        descriptionKey="servicesHub.meta.description"
        pathname={pathname}
        schemaType="ProfessionalService"
      />

      <main className={styles.container}>
        <header className="space-y-4">
          <p className="text-sm uppercase tracking-wide text-neutral-500">
            {t("servicesHub.kicker")}
          </p>
          <h1 className="text-4xl font-semibold tracking-tight text-accent">
            {t("servicesHub.h1")}
          </h1>
          <p className="text-lg text-neutral-600 max-w-3xl">
            {t("servicesHub.lede")}
          </p>
        </header>

        <section className="mt-12 grid gap-6 md:grid-cols-2">
          {Array.isArray(servicesItems)
            ? servicesItems.map((service) => (
                <Link
                  key={service.key}
                  to={service.href}
                  className="group rounded-2xl border border-neutral-200 bg-secondary p-6 shadow-sm hover:-translate-y-0.5 transition-transform"
                >
                  <div className="flex items-start justify-between gap-4">
                    <div>
                      <h2 className="text-xl font-semibold text-accent group-hover:text-accent/90">
                        {service.title}
                      </h2>
                      <p className="mt-2 text-sm text-neutral-600">{service.desc}</p>
                    </div>
                    <span className="text-lg text-accent">→</span>
                  </div>
                </Link>
              ))
            : null}
        </section>
      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full min-h-screen bg-primary text-accent p-4 sm:p-8 lg:p-12",
}